#include <stdio.h>
int main(){
    int A[2][2] = {{1,2},{3,4}};
    int v[2] = {5,6};
    int z[2];
    for(int i=0;i<2;i++){
        z[i]=0;
        for(int j=0;j<2;j++)
            z[i] += A[i][j]*v[j];
    }
    printf("z = [%d, %d]\n", z[0], z[1]);
    return 0;
}

